#include <IOKit/IOKitLib.h>
#include <CoreFoundation/CoreFoundation.h>
#include <cstdio>
#include <vector>
static CFDictionaryRef candidates=nullptr;
static int number(io_registry_entry_t e,CFStringRef k){int n=-1;auto p=IORegistryEntryCreateCFProperty(e,k,0,0);if(p){if(CFGetTypeID(p)==CFNumberGetTypeID())CFNumberGetValue((CFNumberRef)p,kCFNumberIntType,&n);CFRelease(p);}return n;}
static void show(io_registry_entry_t e,int depth){io_name_t name={},cls={};IORegistryEntryGetName(e,name);IOObjectGetClass(e,cls);printf("%*s%s [%s]\n",depth*2,"",name,cls);const char*keys[]={"bConfigurationValue","bInterfaceNumber","bInterfaceClass","bInterfaceSubClass","CameraAssistantBundleID","UsbExclusiveOwner","IOUserClass","IOUserServerName","CFBundleIdentifier","IOProbeScore"};for(auto k:keys){auto key=CFStringCreateWithCString(0,k,kCFStringEncodingUTF8);auto v=IORegistryEntryCreateCFProperty(e,key,0,0);CFRelease(key);if(!v)continue;auto d=CFCopyDescription(v);char text[1024]={};if(d&&CFStringGetCString(d,text,sizeof(text),kCFStringEncodingUTF8))printf("%*s%s=%s\n",depth*2+2,"",k,text);if(d)CFRelease(d);CFRelease(v);}if(candidates&&number(e,CFSTR("bInterfaceClass"))==14){const void*keys[8]={};const void*values[8]={};auto count=CFDictionaryGetCount(candidates);if(count<=8){CFDictionaryGetKeysAndValues(candidates,keys,values);for(CFIndex i=0;i<count;i++){char key[128]={};CFStringGetCString((CFStringRef)keys[i],key,sizeof(key),kCFStringEncodingUTF8);boolean_t matches=false;auto status=IOServiceMatchPropertyTable(e,(CFDictionaryRef)values[i],&matches);printf("%*sREAD-ONLY candidate %s: status=0x%08x matches=%d\n",depth*2+2,"",key,status,matches);}}}if(depth>=8)return;io_iterator_t it=0;if(!IORegistryEntryGetChildIterator(e,kIOServicePlane,&it)){io_registry_entry_t child;while((child=IOIteratorNext(it))){show(child,depth+1);IOObjectRelease(child);}IOObjectRelease(it);}}
int main(int argc,char**argv){CFPropertyListRef plist=nullptr;FILE*f=fopen(argc>1?argv[1]:"src/Driver/Info.plist","rb");if(f){std::vector<UInt8>bytes;UInt8 buf[4096];size_t n;while((n=fread(buf,1,sizeof(buf),f)))bytes.insert(bytes.end(),buf,buf+n);fclose(f);auto data=CFDataCreate(nullptr,bytes.data(),bytes.size());plist=CFPropertyListCreateWithData(nullptr,data,kCFPropertyListImmutable,nullptr,nullptr);CFRelease(data);if(plist&&CFGetTypeID(plist)==CFDictionaryGetTypeID())candidates=(CFDictionaryRef)CFDictionaryGetValue((CFDictionaryRef)plist,CFSTR("IOKitPersonalities"));}io_iterator_t it=0;auto r=IOServiceGetMatchingServices(kIOMainPortDefault,IOServiceMatching("IOUSBHostDevice"),&it);printf("Registry status=0x%08x\n",r);if(r)return 1;unsigned found=0;io_service_t s;while((s=IOIteratorNext(it))){if(number(s,CFSTR("idVendor"))==0x0408&&number(s,CFSTR("idProduct"))==0x209d){found++;show(s,0);}IOObjectRelease(s);}IOObjectRelease(it);printf("Target devices=%u\n",found);if(plist)CFRelease(plist);return found?0:2;}
